import json,html
E=html.escape
ROUTES=[('memory','Memory in practice','Poetry, oral transmission and the science of learning.',['poem-memory','retrieval','vedic','mind-tools']),('collective','A room acting together','Chant, rhythm, trance and the evidence for synchrony.',['chorus','clapping','trance','ritual-data']),('objects','Mind through objects','Paper, print, molecules and traces of early humans.',['paper','jikji-object','receptor','deep-time']),('worlds','Mind across languages and lives','Translation, signed language, social experience and travel.',['translations','signed','social-self','hyecho'])]
def render(root):
 data=json.loads((root/'possibilities.json').read_text());cards=[]
 for d in data:
  steps=''.join(f'<li>{E(t)}</li>' for t in d['steps'])
  cards.append(f'''<article id="{d['id']}" class="possibility" data-areas="{E('|'.join(d['areas']))}" data-mode="{E(d['mode'])}" data-minutes="{d['minutes']}"><div class="possibility-meta"><span>{E(d['mode'])}</span><span>{d['minutes']} min estimate</span></div><h3><a href="#{d['id']}">{E(d['title'])}</a></h3><p class="possibility-object">{E(d['object'])}</p><p>{E(d['idea'])}</p><p class="possibility-areas">{E(' / '.join(d['areas']))}</p><div class="possibility-actions"><button type="button" class="choose" data-pick="{d['id']}" aria-pressed="false" hidden>Add to shortlist<span class="sr-only">: {E(d['title'])}</span></button><a href="{E(d['source']['url'])}">Source</a></div><details><summary>Activity, materials &amp; teaching notes</summary><p><strong>Materials.</strong> {E(d['materials'])}</p><ol>{steps}</ol><p class="possibility-output"><strong>Students produce:</strong> {E(d['output'])}</p><p class="possibility-note">{E(d['note'])}</p><p class="possibility-source"><a href="{E(d['source']['url'])}">{E(d['source']['label'])}</a></p><p class="possibility-status">Proposed teaching adaptation · not classroom-tested here.</p></details></article>''')
 routes=''.join(f'<a class="route" href="?route={id}#collection"><strong>{E(t)}</strong><span>{E(desc)}</span><small>Explore four candidates →</small></a>' for id,t,desc,ids in ROUTES)
 def opts(v):return ''.join(f'<option>{E(x)}</option>' for x in sorted(set(v)))
 return f'''<link rel="stylesheet" href="possibilities.css"><script src="possibilities.js" defer></script><section class="possibilities-opening"><h1>A campus full of possibilities.</h1><p class="standfirst">Read a mind. Train a memory. Make a rhythm. Think with an object.</p><p>MIND(s) can bring a poem, a molecular model, a chant, a sporting action and a philosophical argument into the same common course. These {len(data)} candidates give colleagues concrete ways to contribute.</p><div class="possibilities-intro-links"><a href="#collection">Browse works &amp; activities</a><a href="downloads/mind-gallery-handout.pdf">Six-work handout &amp; QR (PDF)</a><a href="#campus-connections">Find a campus connection</a><a href="history.html">Explore the global history</a></div></section><section class="possibilities-routes"><div><h2>Four ways to begin</h2><p>A selection menu for collaborators—not four required course units.</p></div><div class="route-grid">{routes}</div></section><section id="collection"><div class="possibilities-heading"><h2>Works, objects &amp; activities</h2><p>Each candidate pairs a source with a proposed activity and a concrete student result. Times are planning estimates; preparation and access still need checking.</p></div><form id="possibilities-filters" hidden><label>Search<input id="possibilities-search" type="search" placeholder="Chant, memory, sport, Jikji…"></label><label>Campus connection<select id="possibilities-area"><option value="">All connections</option>{opts(x for d in data for x in d['areas'])}</select></label><label>Activity<select id="possibilities-mode"><option value="">All activities</option>{opts(d['mode'] for d in data)}</select></label><label>Time available<select id="possibilities-time"><option value="">Any duration</option><option value="20">Up to 20 minutes</option><option value="30">Up to 30 minutes</option><option value="45">Up to 45 minutes</option></select></label><button type="button" id="possibilities-reset">Reset filters</button></form><div class="shortlist-bar" id="shortlist-bar" hidden><p id="shortlist-status" role="status" aria-live="polite">No candidates selected</p><button type="button" id="show-shortlist" aria-pressed="false">Show shortlist</button><button type="button" id="print-shortlist" disabled>Print shortlist</button><button type="button" id="clear-shortlist" disabled>Clear shortlist</button></div><div class="possibilities-results"><p id="possibilities-count" role="status" aria-live="polite">{len(data)} candidates</p><a href="possibilities.json" download>Download candidate data</a></div><p id="possibilities-empty" hidden>No candidates match. Reset the filters, or add candidates before showing the shortlist.</p><div class="possibility-grid">{''.join(cards)}</div></section><section id="campus-connections" class="campus-connections"><h2>Many kinds of expertise belong here.</h2><p>These are invitations to contribute, not claims of departmental participation. Connections draw on Lawrence’s <a href="https://lux.lawrence.edu/communities.html">public collections directory</a> and <a href="https://www.lawrence.edu/academics/majors-programs/">academic and campus resources</a>.</p><div class="campus-grid"><article><h3>Conservatory, theatre, dance &amp; athletics</h3><p>Bring ensemble timing, vocal practice, gesture, interpretation and trained movement. Performance can be both a work to study and a way of investigating mind.</p><a href="?area=Music+%26+performance#collection">Performance candidates</a></article><article><h3>Sciences, mathematics &amp; computing</h3><p>Bring molecules, perception, measurement, networks and models. Clarify the difference between an observation, a mechanism and an explanation.</p><a href="?area=Natural+sciences#collection">Science candidates</a></article><article><h3>Humanities, languages &amp; social inquiry</h3><p>Bring translations, religious practices, poetry, argument, history, judgment and accounts of the social self.</p><a href="?area=Anthropology+%26+society#collection">Social and cultural candidates</a></article><article><h3>Libraries, galleries, learning &amp; campus life</h3><p>Bring public collections, accessible formats, study practices, exhibitions and spaces for shared attention. A small display or event can make the proposal tangible.</p><a href="?area=Learning+%26+access#collection">Learning and access candidates</a></article></div></section><section class="possibilities-closing"><h2>From a candidate to a shared experience</h2><p>Choose a work, pair two kinds of expertise, and prepare one short encounter. A faculty demonstration could combine a brief reading, an activity and an example of student work. The shortlist is a starting point for that conversation.</p><p>Sources document works or research; the activities here are editorial proposals, not validated lesson plans. Provider recordings and scores remain with their rights holders. Some candidates need a specialist facilitator, practitioner collaboration or a licensed excerpt.</p><p><a href="participate.html">Contribute a work or activity</a> · <a href="syllabus.html">Read the model syllabus</a></p></section><script type="application/json" id="possibility-routes">{json.dumps({id:ids for id,t,d,ids in ROUTES})}</script>'''
